    "Ces chiffres représentent les notices fictives visibles dans cet onglet. Ils ne sont pas des indicateurs nationaux.": "These figures represent the fictitious records visible in this tab. They are not national indicators.",
    "Ces chiffres sont comptés depuis les registres de l’institution pour l’année civile choisie. Le volume du fonds numérique est un instantané à la date d’établissement ; seules les entrées structurées sont rattachées à une institution d’archives.": "These figures are counted from the institution’s registers for the chosen calendar year. The volume of the digital fonds is a snapshot at the date of preparation; only structured entries are attached to an archives institution.",
    "Ces dépôts seront annulés ; ils n’empêcheront plus de sceller la version. Un fichier déjà déposé et validé n’est pas touché.": "These deposits will be cancelled; they will no longer prevent sealing the version. A file already deposited and validated is not affected.",
    "ces fichiers": "these files",
    "Ces parcours utilisent le backend V13.1. Le mode démonstration n’effectue ni import, ni numérisation, ni extraction. Connectez un compte habilité pour les exécuter.": "These journeys use the V13.1 backend. Demonstration mode performs no import, digitization or extraction. Connect an authorized account to run them.",
