    "Cet acte n’est pas encore scellé. Le scellement automatique n’a pas couvert cet acte : il peut être scellé maintenant.": "This act is not yet sealed. Automatic sealing did not cover this act: it can be sealed now.",
    "Cet archivage est définitif.": "This archiving is final.",
