    "Cet élément n’est lié à aucun document : indiquez-le dans son plan de numérisation.": "This element is linked to no document: state it in its digitization plan.",
    "Cet élément n’est lié à aucun document : les images sont stockées dans une version de document.": "This element is linked to no document: the images are stored in a document version.",
