    "Cet enregistrement ne se modifie pas : un constat plus récent le complète.": "This record cannot be modified: a more recent finding completes it.",
    "Cet événement est déjà constaté : annulez-le d’abord, avec un motif, pour le corriger.": "This event has already been recorded: cancel it first, with a reason, to correct it.",
    "Cet instrument est déjà publié.": "This finding aid is already published.",
    "Cet original est en réserve. Pour le consulter, le numériser, l’exposer ou le prêter, déposez une demande : elle sera autorisée par une autre personne.": "This original is in reserve. To consult, digitize, exhibit or lend it, file a request: it will be authorized by another person.",
    "Cet original n’a pas de numérisation en cours. Pour en produire une représentation numérique, commandez sa numérisation : la sortie sera autorisée par une autre personne et la représentation réceptionnée par une autre personne.": "This original has no digitization in progress. To produce a digital representation, order its digitization: the withdrawal will be authorized by another person and the representation received by another person.",
