    "Cette archive ne peut pas être éliminée : elle est dehors, rattachée à un bien patrimonial, ou son document est essentiel ou sous gel juridique.": "This archive cannot be destroyed: it is out, attached to a heritage item, or its document is essential or under legal hold.",
