    "Cette interface reprend les couleurs nationales et un en-tête républicain. Elle ne constitue pas une charte graphique officielle homologuée. Aucun sceau, armoirie ou logo de ministère non fourni n’a été inventé. Le symbole d’archives est propre au projet ; son adoption doit être validée institutionnellement.": "This interface uses the national colours and a republican header. It is not an officially approved graphic charter. No seal, coat of arms or ministry logo that was not provided has been invented. The archives symbol belongs to the project; its adoption must be validated institutionally.",
