    "Chaque ligne constatée conforme ou en écart devient une notice, en brouillon": "Each line found compliant or with a discrepancy becomes a record, as a draft",
    "Chaque ligne est acceptée ou refusée. L’accusé de réception est délivré à l’enregistrement ; une ligne acceptée sera remise par une troisième personne, une ligne refusée redevient disponible chez le service versant. La personne qui reçoit n’est pas celle qui a soumis.": "Each line is accepted or refused. The acknowledgement of receipt is issued at recording; an accepted line will be handed over by a third person, a refused line becomes available again at the transferring service. The person who receives is not the one who submitted.",
    "Chaque ligne est acceptée ou refusée. Une ligne acceptée sera détruite par une troisième personne ; une ligne refusée redevient disponible. La personne qui vise n’est pas celle qui a soumis.": "Each line is accepted or refused. An accepted line will be destroyed by a third person; a refused line becomes available again. The person who approves is not the one who submitted.",
