    "L’abonnement lié se ferme. L’annulation est validée par une autre personne que celle qui a encaissé, et conservée au journal.": "The linked subscription closes. The cancellation is validated by someone other than the person who collected the payment, and kept in the log.",
    "L’abonnement s’ouvre dès l’enregistrement. Une erreur se corrige ensuite par une annulation motivée, validée par une autre personne.": "The subscription opens as soon as it is recorded. An error is then corrected by a reasoned cancellation, validated by another person.",
    "L’abonnement s’ouvre sans paiement. L’exonération engage l’institution : le motif (décision, convention, qualité du lecteur) est conservé.": "The subscription opens without payment. The exemption binds the institution: the reason (decision, agreement, reader’s status) is kept.",
    "L’acceptation engage l’institution : elle est conservée avec son auteur et sa date. Elle est donnée par une autre personne que celle qui a monté le dossier ; les originaux sont jugés de nouveau à la remise.": "The acceptance binds the institution: it is kept with its author and date. It is given by someone other than the person who put the file together; the originals are assessed again at handover.",
