    "L’assurance prend fin le {n}, avant la nouvelle date de retour : prolongez l’assurance d’abord.": "The insurance ends on {1}, before the new return date: extend the insurance first.",
    "L’atelier de numérisation prend la commande en charge : il choisit le projet et le lot, et crée l’élément de numérisation.": "The digitization workshop takes the order over: it chooses the project and the batch, and creates the digitization element.",
    "L’atelier numérise, indexe et fait contrôler les pages dans le suivi du traitement.": "The workshop digitizes, indexes and has the pages checked in the processing tracking.",
    "L’autorisation engage l’institution : elle est conservée avec son auteur et sa date. Elle est donnée par une autre personne que celle qui a demandé la sortie, et l’original sera jugé de nouveau à la remise.": "The authorization binds the institution: it is kept with its author and date. It is given by someone other than the person who requested the withdrawal, and the original will be assessed again at handover.",
    "L’autorité a refusé toutes les lignes : aucun document n’est détruit, leurs échéances sont de nouveau disponibles.": "The authority refused all the lines: no document is destroyed, their due dates are available again.",
