    "L’état de cet original n’a jamais été constaté.": "The condition of this original has never been recorded.",
    "L’état matériel d’un original se constate, à des dates successives : il ne se saisit pas. L’état matériel du bien est le plus préoccupant des derniers constats de ses originaux.": "An original’s material condition is recorded on successive dates: it is not entered. An item’s material condition is the most worrying of the latest findings of its originals.",
