    "L’événement ne prolonge pas celui qui le précède : un événement a été remplacé, retiré ou réécrit.": "The event does not follow the one before it: an event was replaced, removed or rewritten.",
    "L’événement qui déclenche le délai n’a pas encore été constaté pour ce document ni pour son dossier.": "The event that triggers the period has not yet been recorded for this document or for its file.",
    "L’examen est écrit (30 caractères au moins) et fait par une autre personne que celle qui a proposé la sortie.": "The examination is written (at least 30 characters) and done by someone other than the person who proposed the withdrawal.",
    "L’examen établit la provenance, la situation juridique et les conditions de la prise en charge. Il précède toujours la décision.": "The examination establishes the provenance, the legal situation and the conditions of the takeover. It always precedes the decision.",
    "L’examen juridique et de provenance se rédige en 30 caractères au moins.": "The legal and provenance examination is written in at least 30 characters.",
    "L’exécution d’une destruction ou d’un transfert n’est pas raccordée dans le backend fourni. La lecture des décisions et de leurs blocages reste distincte.": "The execution of a destruction or a transfer is not connected in the supplied backend. The reading of decisions and of their blockers remains separate.",
    "L’exécution des migrations n’est pas activée sur ce serveur : une campagne se prépare, mais ne peut pas être validée tant que l’administration ne l’a pas activée.": "Migration execution is not enabled on this server: a campaign can be prepared, but cannot be validated until the administration has enabled it.",
