    "L’habilitation de dépôt de fichiers est nécessaire dans cette institution.": "The file deposit authorization is required in this institution.",
    "L’horodatage qualifié n’est pas activé sur ce serveur : il exige une autorité d’horodatage, ses certificats de confiance et sa liste de révocation. Ce n’est pas nécessaire pour clore le document ni planifier sa conservation.": "Qualified timestamping is not enabled on this server: it requires a timestamping authority, its trust certificates and its revocation list. It is not necessary to close the document or to schedule its preservation.",
    "L’identifiant du dépôt doit avoir la forme d’un nom de domaine (par exemple archives.exemple.gn).": "The repository identifier must have the form of a domain name (for example archives.example.gn).",
