    "L’identification est activée, mais l’exécutable de l’outil n’est pas valide sur ce serveur : vérifiez son chemin.": "Identification is enabled, but the tool’s executable is not valid on this server: check its path.",
    "L’identification par signature n’est pas activée sur ce serveur : l’outil (Siegfried) n’est pas livré avec l’application, l’administration doit l’installer et l’activer.": "Identification by signature is not enabled on this server: the tool (Siegfried) is not shipped with the application, the administration must install and enable it.",
    "L’identité vient du fournisseur SSO ; les habilitations viennent du backend SNAE-PPD.": "The identity comes from the SSO provider; the permissions come from the SNAE-PPD backend.",
    "L’import est désactivé sur ce serveur. Activation opérateur et antivirus fonctionnel requis.": "Import is disabled on this server. Operator activation and a working antivirus are required.",
