    "La clôture change uniquement l’état de l’entrée. Elle ne certifie pas l’admission, l’intégration ou le scellement des documents.": "Closing only changes the state of the entry. It does not certify the admission, integration or sealing of the documents.",
    "la clôture du document": "the closing of the document",
    "la clôture du dossier": "the closing of the file",
    "La clôture est définitive : plus aucun constat ne pourra être ajouté à cette campagne. Les écarts constatés restent à régulariser.": "Closing is final: no further finding can be added to this campaign. The discrepancies found remain to be regularized.",
    "La commande crée le document qui recevra la numérisation et dépose la demande de sortie de l’original : elle sera autorisée par une autre personne que vous. L’atelier prend ensuite la commande en charge, numérise, puis une autre personne réceptionne la représentation. Il vous faut le droit de créer des documents de l’institution.": "The order creates the document that will receive the digitization and files the request to take the original out: it will be authorized by someone other than you. The workshop then takes the order over, digitizes, and another person receives the representation. You need the right to create documents in the institution.",
    "La commande impose une résolution minimale de {n} dpi : choisissez un lot dont la résolution minimale la respecte, il la fera contrôler page par page.": "The order requires a minimum resolution of {1} dpi: choose a batch whose minimum resolution meets it; it will have it checked page by page.",
    "La configuration du dépôt est incomplète.": "The repository configuration is incomplete.",
    "La configuration du fournisseur d’identité a été refusée. Contactez votre administrateur.": "The identity provider configuration was refused. Contact your administrator.",
    "La confirmation de votre adresse e-mail est nécessaire avant la connexion.": "Confirmation of your e-mail address is required before signing in.",
    "La conformité compare les en-têtes du fichier aux exigences du profil. Elle ne mesure ni la netteté ni l’exactitude des couleurs : ce n’est pas une certification FADGI ou Metamorfoze.": "Compliance compares the file’s headers with the profile’s requirements. It measures neither sharpness nor color accuracy: it is not a FADGI or Metamorfoze certification.",
    "La connexion à ce compte est suspendue. Contactez votre administrateur.": "Sign-in to this account is suspended. Contact your administrator.",
