    "La création du compte et la récupération du mot de passe relèvent de votre fournisseur d’identité. Ce portail ne crée pas de mot de passe local. La fermeture de l’onglet n’assure pas la déconnexion du fournisseur SSO.": "Account creation and password recovery are handled by your identity provider. This portal does not create a local password. Closing the tab does not log you out of the SSO provider.",
