    "La notice patrimoniale ne publie rien et ne change aucune confidentialité : la diffusion se décide séparément, bien par bien.": "The heritage record publishes nothing and changes no confidentiality: dissemination is decided separately, item by item.",
    "La nouvelle fin doit suivre la fin actuelle ({n}).": "The new end must follow the current end ({1}).",
    "La nouvelle fin est aussi la nouvelle date de retour de chaque original. L’assurance doit couvrir cette date : prolongez-la d’abord si besoin.": "The new end is also the new return date of each original. The insurance must cover this date: extend it first if needed.",
