    "La numérisation a échoué. Vérifiez le scanner et son profil NAPS2.": "Digitization failed. Check the scanner and its NAPS2 profile.",
    "La numérisation d’un original se commande : la sortie est autorisée par une autre personne, l’atelier numérise dans le suivi du traitement, l’original ne rentre qu’après le contrôle qualité des pages, puis une autre personne réceptionne la représentation numérique, qui reste reliée au bien.": "The digitization of an original is ordered: the departure is authorized by another person, the workshop digitizes in the processing tracking, the original only comes back after the pages’ quality control, then another person receives the digital representation, which stays linked to the item.",
    "La page {n} existe déjà : marquez-la « à rescanner » avant de la remplacer.": "Page {1} already exists: mark it “to rescan” before replacing it.",
    "La page n’a pas pu être chargée. Vous avez peut-être atteint la limite de lecture par heure, ou votre session a pris fin.": "The page could not be loaded. You may have reached the hourly reading limit, or your session has ended.",
    "La page restera en attente d’un nouveau fichier ; l’élément ne pourra pas être terminé sans justification.": "The page will remain waiting for a new file; the element cannot be completed without justification.",
    "la page signalée": "the flagged page",
    "La période d’effet ne couvre pas aujourd’hui.": "The period of effect does not cover today.",
    "La période dépasse celle de votre attribution.": "The period exceeds that of your assignment.",
    "La personne qui détruit.": "The person who destroys.",
    "La phase courante n’est pas terminée.": "The current phase is not finished.",
    "La phase courante ne peut pas durer plus que la conservation totale.": "The current phase cannot last longer than the total retention.",
    "La place de la fonction dans un plan de classement ou un cadre de référence.": "The place of the function in a classification plan or a reference framework.",
    "La portée doit correspondre aux rattachements institution / département.": "The scope must match the institution / department attachments.",
    "La posture est déclarée par la configuration : le serveur ne peut pas constater l’emplacement physique d’un stockage. Elle ne remplace pas un plan de reprise testé.": "The posture is declared by the configuration: the server cannot verify the physical location of a storage. It does not replace a tested recovery plan.",
