    "la quantité ne peut pas être négative.": "the quantity cannot be negative.",
    "La quittance remise au lecteur au guichet.": "The receipt given to the reader at the counter.",
    "La raison qui justifie de cacher cette zone : donnée personnelle, secret protégé…": "The reason for hiding this area: personal data, protected secret…",
    "La ranger à son emplacement habituel puis constater sa présence, ou faire de cet emplacement son emplacement habituel.": "Put it back in its usual location then record its presence, or make this location its usual location.",
    "La réception confirme que la représentation numérique correspond à l’original et reste reliée au bien. Elle est faite par une autre personne que celle qui a commandé la numérisation.": "The receipt confirms that the digital representation matches the original and stays linked to the item. It is done by someone other than the person who ordered the digitization.",
    "La recherche porte sur les notices locales de démonstration.": "The search covers the local demonstration records.",
    "La référence « {n} » apparaît plusieurs fois dans le bordereau.": "The reference “{1}” appears several times in the schedule.",
