    "La référence du visa est limitée à 255 caractères.": "The visa reference is limited to 255 characters.",
    "La référence du visa est obligatoire pour accepter des lignes.": "The visa reference is required to accept lines.",
    "la référence est limitée à 150 caractères.": "the reference is limited to 150 characters.",
    "La référence est limitée à 150 caractères.": "The reference is limited to 150 characters.",
