    "Le demandeur confirme qu’il a bien reçu l’original ; le retour s’enregistre quand l’original rentre.": "The requester confirms having received the original; the return is recorded when the original comes back.",
    "Le dépôt est terminé. Un agent habilité doit valider le fichier depuis la fiche documentaire avant l’extraction. Une fois cette validation faite, relisez le dépôt ou reprenez l’extraction.": "The upload is finished. An authorized agent must validate the file from the document record before extraction. Once this validation is done, reread the upload or resume the extraction.",
