    "Le numéro porté au registre (150 caractères au plus), unique dans l’institution. À défaut, renseignez la cote.": "The number entered in the register (150 characters at most), unique within the institution. Otherwise, fill in the call number.",
    "Le paquet doit être celui dont le bordereau a été repris. Les lignes constatées absentes ne sont pas déposées. Renvoyer le même paquet ne redépose rien et retente ce qui a échoué.": "The package must be the one whose schedule was resumed. Lines found absent are not deposited. Sending the same package again deposits nothing again and retries what failed.",
