    "Le plan de classement n’a pas pu être lu : la règle peut viser des types de documents seulement.": "The classification plan could not be read: the rule can only target document types.",
    "Le plan est relu et reste en vigueur sans changement de contenu": "The plan is reread and stays in force with no change of content",
    "Le plus ancien :": "The oldest:",
    "Le portail ne propose que les formules actives. Les tarifs, les durées et les catégories de lecteurs sont fixés par l’institution : rien n’est préenregistré. Une formule modifiée ne change pas les abonnements déjà demandés.": "The portal only offers active plans. The prices, durations and reader categories are set by the institution: nothing is pre-recorded. A modified plan does not change the subscriptions already requested.",
    "Le préfixe compte 8 caractères au plus, parmi les chiffres et les consonnes b c d f g h j k m n p q r s t v w x z.": "The prefix has 8 characters at most, among the digits and the consonants b c d f g h j k m n p q r s t v w x z.",
    "Le premier événement ne prolonge pas l’historique antérieur.": "The first event does not follow the earlier history.",
