    "Le prénom est obligatoire.": "The first name is required.",
    "Le prix de chaque ligne est celui du tarif au jour de la commande. L’encaissement est fait au guichet : on enregistre ici sa référence (quittance), le système n’exécute aucun paiement. Les reproductions ne sont remises qu’une fois l’encaissement enregistré.": "The price of each line is that of the rate on the day of the order. Payment is collected at the counter: its reference (receipt) is recorded here, the system executes no payment. Reproductions are only handed over once the payment is recorded.",
