    "Une étape d’un circuit de validation attend une personne de votre rôle.": "A step of a validation circuit is waiting for a person with your role.",
    "Une exposition réunit les originaux que l’institution montre dans un lieu, avec ses dates. Elle est acceptée par une autre personne que vous ; chaque original sort ensuite par une demande de mouvement, avec un constat d’état au départ et au retour.": "An exhibition groups the originals the institution shows in a venue, with its dates. It is accepted by someone other than you; each original then leaves through a movement request, with a condition report at departure and at return.",
